select date_format(c.signup_date, 'yyyy-MM') as signup_month, case when c.country in ('US', 'JP') then 'tier_1' else 'other' end as country_group, min(s.end_date) as first_end_date from subscriptions s join customers c on s.customer_id = c.id where c.is_active = false group by date_format(c.signup_date, 'yyyy-MM'), case when c.country in ('US', 'JP') then 'tier_1' else 'other' end;
